let dialog=null,dialogDraft=null,dialogTitle='',dialogBody=null,opener=null,confirmRun=null,tour=null;

function placeDialog(){if(!dialog)return;const r=document.querySelector('.app-frame').getBoundingClientRect();dialog.style.setProperty('--frame-h',r.height+'px');dialog.style.width=Math.min(dialogTitle==='Edit MCP server'||dialogTitle==='Add MCP server'?760:640,r.width-48)+'px';dialog.style.left=(r.left+r.width/2)+'px';dialog.style.top=Math.max(12,r.top+20)+'px';}

function redrawDialog(){if(!dialog)return;const active=dialog.contains(document.activeElement)?document.activeElement:null,scroll=dialog.scrollTop,selection=active&&typeof active.selectionStart==='number'?[active.selectionStart,active.selectionEnd]:null,selector=active?.id?'#'+CSS.escape(active.id):active?.dataset.b?`[data-b="${CSS.escape(active.dataset.b)}"][data-v="${CSS.escape(active.dataset.v||'')}"]`:null,disclosures=[...dialog.querySelectorAll('details')].map(x=>x.open);dialog.innerHTML=`<div class="modal-head"><h2>${E(dialogTitle)}</h2>${btn('✕','dialog-close','','',`aria-label="Close ${E(dialogTitle)}"`)}</div><div class="b-dialog-preview">Preview · local state only</div><div class="b-dialog-content">${dialogBody()}</div><div id="b-dialog-error" class="b-danger" role="alert"></div>`;placeDialog();dialog.querySelectorAll('details').forEach((x,i)=>x.open=disclosures[i]||false);const next=selector&&dialog.querySelector(selector);if(next){next.focus({preventScroll:true});if(selection)try{next.setSelectionRange(...selection);}catch{}}dialog.scrollTop=scroll;}

function closeDialog(){if(!dialog)return;const old=dialog;dialog=null;old.close();old.remove();dialogDraft=null;confirmRun=null;document.querySelectorAll('.b-spotlit').forEach(x=>x.classList.remove('b-spotlit'));tour=null;opener?.focus?.();}

function openDialog(title,body,draft={}){if(dialog)closeDialog();opener=document.activeElement;dialogTitle=title;dialogBody=body;dialogDraft=draft;dialog=document.createElement('dialog');dialog.className='modal-card b-dialog';dialog.setAttribute('aria-label',title);document.body.append(dialog);redrawDialog();dialog.addEventListener('cancel',e=>{e.preventDefault();if(tour)skipTours();closeDialog();});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});dialog.showModal();(dialog.querySelector('input:not([readonly]),select,textarea,button:not([data-b="dialog-close"])')||dialog).focus();}

function error(text){const el=document.getElementById('b-dialog-error');if(el)el.textContent=text;else notice(text,true);}

function notice(text,bad=false){H.state.toastText='Preview: '+text;B().notice=bad?text:null;H.redraw();}

function confirm(title,text,label,run,danger=true){openDialog(title,()=>`<div>${text}</div><div class="page-actions">${btn('Cancel','dialog-close')}${btn(label,'confirm','',!danger,danger?'data-danger="true"':'')}</div>`);confirmRun=run;}

function finish(text){closeDialog();notice(text);}

function toJson(s){return s.transport==='stdio'?{type:'stdio',command:s.command,args:s.args,env:Object.fromEntries(s.env)}:{type:s.transport,url:s.url,headers:Object.fromEntries(s.headers)};}

function readJson(){if(dialogDraft.mode!=='json')return true;try{const j=JSON.parse(dialogDraft.json);if(!j||Array.isArray(j)||typeof j!=='object')throw Error('expected a server object');const t=j.type||(j.url?'http':'stdio');if(!['stdio','http','sse'].includes(t))throw Error('type must be stdio, http or sse');for(const key of ['command','url'])if(j[key]!=null&&typeof j[key]!=='string')throw Error(key+' must be a string');if(j.args&&(!Array.isArray(j.args)||j.args.some(x=>typeof x!=='string')))throw Error('args must be an array of strings');for(const k of ['env','headers'])if(j[k]&&(Array.isArray(j[k])||typeof j[k]!=='object'||Object.values(j[k]).some(x=>typeof x!=='string')))throw Error(k+' must contain string values');Object.assign(dialogDraft,{transport:t,command:j.command||'',args:j.args||[],env:Object.entries(j.env||{}),url:j.url||'',headers:Object.entries(j.headers||{})});return true;}catch(e){error('The JSON is not a server: '+e.message);return false;}}

function mcpForm(){const f=dialogDraft;const pairs=k=>`${f[k].map(([name,value],i)=>`<div class="b-kv">${field(k+'-'+i+'-0',k==='env'?'NAME':'Header',name)}${field(k+'-'+i+'-1','Value',value,'password')}${btn('Show','reveal',k+'-'+i+'-1')}${btn('Remove','mcp-del',k+':'+i)}</div>`).join('')}${btn('+ Add '+(k==='env'?'variable':'header'),'mcp-row',k)}`;return `${field('name','Name *',f.name,'text',f.editing?'readonly title="The name is the key in every tool’s config"':'')}<div class="b-toolbar"><b>Connection</b>${['form','json'].map(x=>btn(x==='form'?'Form':'JSON','mcp-mode',x)).join('')}</div>${f.mode==='json'?`<label for="b-json">Claude Code server JSON</label><textarea id="b-json" class="mono" data-b-field="json" rows="12">${E(f.json)}</textarea>`:`${select('transport','Transport',f.transport,[['stdio','Local command (stdio)'],['http','HTTP'],['sse','SSE']])}${f.transport==='stdio'?`${field('command','Command *',f.command)}<b>Arguments</b>${f.args.map((a,i)=>`<div class="b-kv">${field('arg-'+i,'Argument '+(i+1),a)}${btn('Remove','mcp-del','args:'+i)}</div>`).join('')}${btn('+ Add argument','mcp-row','args')}<b>Environment variables</b>${pairs('env')}`:`${field('url','URL *',f.url)}<b>Headers</b>${pairs('headers')}`}`}<b>Write to</b><div class="b-toolbar">${shown().map(t=>`<label class="filter-chip"><input type="checkbox" data-b="mcp-target" data-v="${t.id}" ${f.targets.includes(t.id)?'checked':''}/> ${icon(t.id)} ${E(t.label)}${t.installed?'':' (not installed)'}</label>`).join('')}</div><details><summary>Description & links · never written to a tool</summary>${field('description','Description',f.description)}${field('homepage','Homepage or docs',f.homepage)}</details><div class="page-actions">${btn('Cancel','dialog-close')}${btn(f.editing?'Save':'Add server','mcp-save','',true)}</div>`;}

function editMcp(name){const it=M().items.mcp.find(s=>s.name===name);const f=it?{...copy(it),env:Object.entries(it.env),headers:Object.entries(it.headers),editing:true,targets:M().items.targets.filter(t=>t.kind==='mcp'&&t.item===name).map(t=>t.harness),mode:'form'}:{name:'',transport:'stdio',command:'',args:[],env:[],url:'',headers:[],description:'',homepage:'',targets:shown().some(t=>t.id==='claude'&&t.installed)?['claude']:[],editing:false,mode:'form'};openDialog(it?'Edit MCP server':'Add MCP server',mcpForm,f);}

